pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 amount, bytes memory data) public {
        // Bound amount to a reasonable range to avoid overflow and ensure sufficient balance
        amount = bound(amount, 1, 100 ether);
        // Ensure sender is not the owner
        vm.assume(sender != address(this));
        vm.assume(sender != c.owner());
        // Deploy a helper that reverts on receiving ETH
        Reverter r = new Reverter();
        // Fund the contract with enough ETH
        vm.deal(address(c), amount);
        // Fund the sender so they can call (but not needed for value, since sendMoney sends from c's balance)
        vm.deal(sender, 0);
        // Record balance before
        uint256 balBefore = address(c).balance;
        // Prank as non-owner sender calling sendMoney to the reverter
        vm.prank(sender);
        // sendMoney to the reverting target should revert
        try c.sendMoney(address(r), amount, data) {
            // If it does not revert, the call succeeded but the target reverted? That's impossible.
            // Actually, low-level call to a reverting target returns false, and sendMoney reverts on false.
            // So we expect this to always revert.
            // If by some chance it succeeds (it shouldn't), we record it.
            assert(false);
        } catch {
            // Expected: sendMoney reverted because target reverted
        }
        // After the failed sendMoney, balance must remain unchanged
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

