pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 successMode) public {
        // Restrict to admissible domain: nonzero amount so side-effect is observable
        amount = bound(amount, 1, address(c).balance > 0 ? address(c).balance : type(uint256).max);
        // Give contract some Ether to withdraw
        vm.deal(address(c), amount);
        // Deploy a helper whose behavior is controlled by the fuzzer
        // successMode: 0 -> succeed, any other -> revert
        Helper helper = new Helper();
        vm.deal(address(helper), 0);
        // Fund the owner (address(this) is the owner in setUp)
        vm.deal(address(this), 0);

        bool ok;
        bytes memory data = successMode == 0 ? hex"" : hex"dead";
        try c.sendMoney(address(helper), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the owner can always successfully execute a sendMoney call to a cooperative recipient
        // The bug breaks this by making onlyOwner revert for the actual owner, causing ok == false for successMode == 0
        assertTrue(ok);
    }
}

contract Helper {
    fallback() external payable {
        // If data is empty, succeed (do nothing)
        // If data is non-empty, revert
        if (msg.data.length > 0) {
            revert();
        }
    }
}

