contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to be within the contract's balance after funding
        uint256 fundAmount = 10 ether;
        vm.deal(address(c), fundAmount);
        // Bound the withdrawal amount to be within the contract's balance to avoid revert due to insufficient funds
        bound(amount, 0, fundAmount);

        // Ensure the owner makes the call
        address owner = c.owner();
        vm.prank(owner);

        uint256 balanceBefore = address(c).balance;
        // The contract should not revert for valid amounts
        c.withdraw(amount);
        uint256 balanceAfter = address(c).balance;

        // The rule: after a successful withdraw, the balance must decrease by the amount withdrawn
        assertTrue(balanceBefore - amount == balanceAfter);
    }
}

